-- Reforge production schema extension. Apply after the base profiles/projects/project_members/notes/myria_goals tables.
create schema if not exists private;
alter table public.profiles add column if not exists role text not null default 'user';
alter table public.profiles add column if not exists settings jsonb not null default '{}'::jsonb;
create table if not exists public.sections(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,title text not null,slug text not null,position integer not null default 0,is_system boolean not null default false,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(project_id,slug));
alter table public.notes add column if not exists section_id uuid references public.sections(id) on delete cascade;
alter table public.notes add column if not exists position integer not null default 0;
alter table public.myria_goals add column if not exists title text not null default '';
alter table public.myria_goals add column if not exists description text not null default '';
alter table public.myria_goals add column if not exists reason text not null default '';
alter table public.myria_goals add column if not exists priority integer not null default 50;
create table if not exists public.myria_tasks(id uuid primary key default gen_random_uuid(),goal_id uuid not null references public.myria_goals(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,description text not null,status text not null default 'planned',risk_level text not null default 'low' check(risk_level in('low','medium','high')),attempts integer not null default 0,max_attempts integer not null default 3 check(max_attempts between 1 and 3),expected_result text not null default '',actual_result text not null default '',verification text not null default '',reflection text not null default '',created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.myria_activity(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,goal_id uuid references public.myria_goals(id) on delete set null,task_id uuid references public.myria_tasks(id) on delete set null,status text not null,reason text not null default '',action text not null default '',resources text[] not null default '{}',result text not null default '',verification text not null default '',reflection text not null default '',retry_count integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.myria_memory(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,memory_key text not null,memory_value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),unique(project_id,user_id,memory_key));
create table if not exists public.myria_conversations(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('user','assistant')),content text not null,created_at timestamptz not null default now());
create table if not exists public.project_invites(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,email text not null,role text not null default 'editor' check(role in('editor','viewer')),status text not null default 'pending' check(status in('pending','accepted','revoked')),invited_by uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),accepted_at timestamptz,unique(project_id,email,status));
alter table public.sections enable row level security;alter table public.myria_tasks enable row level security;alter table public.myria_activity enable row level security;alter table public.myria_memory enable row level security;alter table public.myria_conversations enable row level security;alter table public.project_invites enable row level security;
create or replace function private.has_project_access(pid uuid,require_edit boolean default false) returns boolean language sql stable security definer set search_path=public,auth,pg_temp as $$select auth.uid() is not null and exists(select 1 from public.project_members pm where pm.project_id=pid and pm.user_id=auth.uid() and(not require_edit or pm.role in('owner','editor')))$$;
revoke all on function private.has_project_access(uuid,boolean) from public;grant usage on schema private to authenticated;grant execute on function private.has_project_access(uuid,boolean) to authenticated;
create or replace function private.is_project_owner(pid uuid) returns boolean language sql stable security definer set search_path=public,auth,pg_temp as $$select auth.uid() is not null and exists(select 1 from public.projects p where p.id=pid and p.owner_id=auth.uid())$$;
revoke all on function private.is_project_owner(uuid) from public;grant execute on function private.is_project_owner(uuid) to authenticated;
create or replace function private.shares_project_with(target_user uuid) returns boolean language sql stable security definer set search_path=public,auth,pg_temp as $$select auth.uid()=target_user or exists(select 1 from public.project_members a join public.project_members b on b.project_id=a.project_id where a.user_id=auth.uid() and b.user_id=target_user)$$;
revoke all on function private.shares_project_with(uuid) from public;grant execute on function private.shares_project_with(uuid) to authenticated;
create or replace function public.handle_new_reforge_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.profiles(user_id,display_name) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'Creator')) on conflict(user_id) do nothing;return new;end$$;
revoke all on function public.handle_new_reforge_user() from public,anon,authenticated;drop trigger if exists on_auth_user_created_reforge on auth.users;create trigger on_auth_user_created_reforge after insert on auth.users for each row execute function public.handle_new_reforge_user();
create or replace function public.handle_new_reforge_project() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare titles text[]:=array['Brainstorming','Outlines','Characters','Worldbuilding','Locations','Lore','Power Systems','Plot Development','Themes','Research','Rough Draft','Final Draft'];t text;pos int:=0;begin insert into public.project_members(project_id,user_id,role) values(new.id,new.owner_id,'owner') on conflict do nothing;foreach t in array titles loop insert into public.sections(project_id,title,slug,position,is_system,created_by) values(new.id,t,lower(regexp_replace(t,'[^a-zA-Z0-9]+','-','g')),pos,true,new.owner_id) on conflict(project_id,slug) do nothing;pos:=pos+1;end loop;return new;end$$;
revoke all on function public.handle_new_reforge_project() from public,anon,authenticated;drop trigger if exists on_reforge_project_created on public.projects;create trigger on_reforge_project_created after insert on public.projects for each row execute function public.handle_new_reforge_project();
create or replace function public.accept_project_invite(invite_id uuid) returns void language plpgsql security definer set search_path=public,auth,pg_temp as $$declare inv public.project_invites%rowtype;requester_email text;begin if auth.uid() is null then raise exception 'Authentication required';end if;requester_email:=lower(coalesce(auth.jwt()->>'email',''));select * into inv from public.project_invites where id=invite_id and status='pending' for update;if inv.id is null then raise exception 'Invite not found';end if;if requester_email='' or lower(inv.email)<>requester_email then raise exception 'Invite belongs to another email';end if;insert into public.project_members(project_id,user_id,role) values(inv.project_id,auth.uid(),inv.role) on conflict(project_id,user_id) do update set role=excluded.role;update public.project_invites set status='accepted',accepted_at=now() where id=invite_id;end$$;
revoke all on function public.accept_project_invite(uuid) from public,anon;grant execute on function public.accept_project_invite(uuid) to authenticated;
